function validate(input) {
  const [{ Weather = [] }] = input;
  const seen = new Set();
  for (const [city, day, degree] of Weather) {
    if (city === null || day === null) return 'Every reading needs a city_id and a day.';
    if (degree === null) return `City ${city} on ${day} needs a degree.`;
    const key = `${city}|${day}`;
    if (seen.has(key)) return `City ${city} has two readings on ${day}.`;
    seen.add(key);
  }
  return null;
}

