function generate(rand, size) {
  const pad = value => String(value).padStart(2, '0');
  const dayAt = offset => {
    const d = new Date(Date.UTC(2021, 11, 25) + offset * 86400000);
    return `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}`;
  };
  const Weather = [];
  if (size === 'small') {
    // Few cities, few days and a narrow degree range, so maxima tie often.
    const cities = [1, 2, 3, 4], days = [0, 3, 7, 8, 30, 200].map(dayAt);
    const pairs = [];
    for (const city of cities) for (const day of days) pairs.push([city, day]);
    for (let i = pairs.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [pairs[i], pairs[j]] = [pairs[j], pairs[i]]; }
    const count = Math.floor(rand() * 9);
    for (const [city, day] of pairs.slice(0, count)) Weather.push([city, day, Math.floor(rand() * 5) - 3]);
  } else {
    // 40 cities with 50 readings each, inserted in shuffled order.
    for (let city = 1; city <= 40; city++) for (let k = 0; k < 50; k++) Weather.push([city, dayAt(k * 7 + Math.floor(rand() * 7)), Math.floor(rand() * 30) - 10]);
    for (let i = Weather.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [Weather[i], Weather[j]] = [Weather[j], Weather[i]]; }
  }
  return [{ Weather }];
}
